async function transport(path,method='GET',body,options={}) {if(localApi)return (await localApi)(path,method,body);let r;try{r=await fetch(`${API}/api/${path}`,{method,signal:AbortSignal.timeout(method==='POST'&&path.startsWith('ai/')?185000:15000),credentials:Capacitor.isNativePlatform()||API?'omit':'same-origin',headers:{'Content-Type':'application/json',...(token?{Authorization:`Bearer ${token}`}:{}),...(options.idempotencyKey?{'Idempotency-Key':options.idempotencyKey}:{})},...(body?{body:JSON.stringify(body)}:{})});}catch(error){throw new Error(path.startsWith('ai/jobs')||path==='ai/program-draft'?(error?.name==='TimeoutError'?'AI request timed out. Your saved job can be resumed.':'AI connection was lost. Reopen the saved job to resume.'):API?NETWORK_MESSAGE:'Server unavailable. Try again.');}const data=await r.json();if(!r.ok){const error=new Error(data.error || 'Request failed');error.code=data.code;error.status=r.status;throw error;}if(data.token)token=data.token;return data;}
async function api(path,method='GET',body,options={}){
 const queued=method==='POST'&&['log','tracker'].includes(path)?workoutOutbox.enqueue(activeOwner,path,body):null;
 try{const data=await transport(path,method,queued?{...queued.body,clientRequestId:queued.clientRequestId}:body,options);if(data.user)activeOwner=data.user.id;if(queued)workoutOutbox.remove(queued.clientRequestId);if(path==='logout'||path==='account'&&method==='DELETE')activeOwner='';return data;}catch(e){if(queued)e.message+=' Your workout is kept on this device. Retry it in Account & settings after reconnecting.';throw e;}
}
const days=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const dateString=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const localDate=s=>new Date(s+'T12:00:00');
const repeatSummary=log=>{const metcon=log.blockResults?.find(r=>r.status!=='skipped');if(metcon)return scoreText(metcon.score);const actual=(log.exercises||[]).flatMap(e=>(e.sets||[]).filter(s=>s.completed!==false));const best=actual.filter(s=>s.load!=null).sort((a,b)=>Number(b.load)-Number(a.load))[0];if(best)return `top load ${best.load} ${best.loadUnit||'lbs'} × ${best.reps??'—'}`;const meters=actual.reduce((n,s)=>n+(s.distance||0)*(s.distanceUnit==='km'?1000:s.distanceUnit==='mi'?1609.344:s.distanceUnit==='yd'?.9144:1),0),seconds=actual.reduce((n,s)=>n+(s.durationSeconds||0),0);return meters?`${Math.round(meters)} m · ${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`:seconds?`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`:'Actual result recorded'};
function monday(d){const r=new Date(d);r.setDate(r.getDate()-((r.getDay()+6)%7));return r;}
function sessionDate(a,week,s){return localDate(scheduledDate(a,week,a.plan.find(w=>w.week===week).sessions.indexOf(s)));}
const clone=x=>JSON.parse(JSON.stringify(x));
const initials=s=>s.split(' ').slice(0,2).map(x=>x[0]).join('');
const blankItem=newPrescription;
const nav=[['overview','Overview',LayoutDashboard],['athletes','Athletes',Users],['programs','Programs',ClipboardList],['metcon-builder','MetCon Builder',Flame],['calendar','Calendar',CalendarDays],['exercises','Exercise library',Dumbbell],['progression','Progression',TrendingUp],['stats','Goals & Progress',Target],['volume','Exercise Progress',Activity],['ai-builder','AI Program Builder',Sparkles],['ai-review','AI Draft Review',ClipboardList]];

function Button({children,variant='',className='',...props}){return <button className={`btn ${variant} ${className}`} {...props}>{children}</button>}
function Badge({children,type=''}){return <span className={`badge ${type}`}>{children}</span>}
function Logo({large=false}){return <div className={`brand ${large?'large':''}`}><img className="brand-heart" src="/iron-heart-logo.png" alt="Iron Heart anatomical heart logo"/><img className="brand-wordmark" src="/iron-heart-wordmark.png" alt="Iron Heart Strength"/></div>}
function Field({label,children}){return <label className="field"><span>{label}</span>{children}</label>}
function Modal({title,children,onClose,wide=false}){
  const ref=useRef();useEffect(()=>{const d=ref.current;d.showModal();return()=>d.close();},[]);
  return <dialog ref={ref} className={wide?'wide':''} onCancel={e=>{e.preventDefault();onClose();}} onClick={e=>{if(e.target===ref.current)onClose();}}><div className="dialog-heading"><h2>{title}</h2><button className="icon-button" aria-label="Close dialog" onClick={onClose}><X size={20}/></button></div>{children}</dialog>;
}
