  const logFor=(a,w,si)=>data.logs.find(l=>l.assignmentId===a.id&&l.week===w&&l.session===si);
  const assessmentBenchmark=(a,w,si,log)=>{const definitions=dataRef.current?.savedBenchmarks||data.savedBenchmarks||[];return definitions.find(d=>d.scoring?.protocol==='six_minute_max_run'&&(log?.benchmarkId?d.id===log.benchmarkId:d.programId===a.programId&&d.week===w&&d.sessionIndex===si));};
  const editWorkout=log=>{if(log.source==='tracker'){show('tracker-edit',{log});return;}const assignment=data.assignments.find(a=>a.id===log.assignmentId);if(!assignment){setError('The assigned program is no longer available. This workout can still be reviewed, but editing needs its original assignment.');return;}show('workout',{assignment,week:log.week,session:log.session,existingLog:log,assessmentBenchmark:assessmentBenchmark(assignment,log.week,log.session,log)});};
